<template><el-card shadow="never" v-loading="loading"><el-tabs v-model="tab" @tab-change="load"><el-tab-pane label="预算执行" name="budget-execution" /><el-tab-pane label="支出明细" name="expenses" /><el-tab-pane label="付款记录" name="payments" /><el-tab-pane label="审计日志" name="audit" /></el-tabs><div class="toolbar"><el-input v-model="query" placeholder="搜索当前报表" clearable /><el-button @click="downloadCsv">导出 CSV</el-button></div><el-table :data="filtered" height="520" empty-text="暂无数据"><el-table-column v-for="key in columns" :key="key" :prop="key" :label="labels[key]||key" min-width="150"><template #default="{row}">{{cell(row[key])}}</template></el-table-column></el-table></el-card></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{financeApi}from'@/api/finance';const loading=ref(false),tab=ref<'budget-execution'|'expenses'|'payments'|'audit'>('budget-execution'),rows=ref<Record<string,unknown>[]>([]),query=ref('');const labels:Record<string,string>={project_name:'项目',category:'预算科目',amount:'金额',reserved_amount:'占用',spent_amount:'支出',available_amount:'可用',expense_date:'支出日期',payment_no:'付款单号',status:'状态',action:'动作',entity_type:'对象类型',entity_id:'对象ID',created_at:'时间'};const columns=computed(()=>{const preferred=Object.keys(labels).filter(key=>rows.value.some(row=>key in row));return preferred.length?preferred:Object.keys(rows.value[0]||{}).slice(0,10)});const filtered=computed(()=>{const q=query.value.toLowerCase();return q?rows.value.filter(row=>JSON.stringify(row).toLowerCase().includes(q)):rows.value});function cell(value:unknown){if(value===null||value===undefined||value==='')return '-';if(typeof value==='object')return JSON.stringify(value);return String(value)}async function load(){loading.value=true;try{const result=await financeApi.report<{records:Record<string,unknown>[]}>(tab.value);rows.value=result.records||[]}finally{loading.value=false}}function downloadCsv(){const escape=(v:unknown)=>`"${cell(v).replaceAll('"','""')}"`;const csv=[columns.value.map(escape).join(','),...filtered.value.map(row=>columns.value.map(key=>escape(row[key])).join(','))].join('\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`finance-${tab.value}-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url)}onMounted(load)</script>
<style scoped>.toolbar{display:flex;gap:10px;margin-bottom:12px}.toolbar .el-input{max-width:360px}</style>
